def plan(p,name,price,sub,body,fine,cta,featured=False):
    base=NAVY if featured else WHITE
    txtc=WHITE if featured else NAVY
    kids=[]
    if featured: kids.append(el(tx('Most Popular','p',{"margin":"0","color":WHITE,"fontSize":"0.8125rem","fontWeight":"700","textTransform":"uppercase","letterSpacing":"0.12em"},p=p),{"position":"absolute","top":"-1rem","left":"50%","transform":"translateX(-50%)","backgroundColor":RED,"borderTopLeftRadius":"9999px","borderTopRightRadius":"9999px","borderBottomLeftRadius":"9999px","borderBottomRightRadius":"9999px","paddingTop":"0.4rem","paddingRight":"1.25rem","paddingBottom":"0.4rem","paddingLeft":"1.25rem"},p=p))
    kids.append(tx(name,'h3',{"color":txtc,"marginBottom":"0.5rem"},p=p))
    kids.append(tx(price,'p',{"fontFamily":"Lora, serif","fontSize":"3.25rem","fontWeight":"700","lineHeight":"1","color":(CREAM if featured else RED),"margin":"0"},p=p))
    if sub: kids.append(tx(sub,'p',{"margin":"0.4rem 0 0","color":txtc,"fontWeight":"600","fontSize":"0.9375rem"},p=p))
    kids.append(tx(body,'p',{"color":txtc,"margin":"1.25rem 0 0"},p=p))
    if fine: kids.append(tx(fine,'p',{"color":txtc,"margin":"1rem 0 0","fontStyle":"italic","fontSize":"0.9375rem","opacity":"0.85"},p=p))
    kids.append(el(cta,{"marginTop":"auto","paddingTop":"1.75rem","display":"flex"},p=p))
    st={"backgroundColor":base,"position":"relative","display":"flex","flexDirection":"column",**R12,"boxShadow":("0 24px 48px rgba(10,31,68,0.35)" if featured else "0 6px 18px rgba(0,0,0,0.08)"),**pad("2.25rem"),"paddingTop":("3rem" if featured else "2.25rem"),"borderTopWidth":"6px","borderTopStyle":"solid","borderTopColor":(RED if featured else TEAL),**LIFT}
